"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/cta-sections/variants/01-sunflower";
import View1 from "./components/cta-sections/variants/02-floating-gallery";
import View2 from "./components/cta-sections/variants/03-portrait-frame";
import View3 from "./components/cta-sections/variants/04-product-window";
import View4 from "./components/cta-sections/variants/05-proof-orbit";
import View5 from "./components/cta-sections/variants/06-shade-panel";
import View6 from "./components/cta-sections/variants/07-glow";
import View7 from "./components/cta-sections/variants/08-terminal";
import View8 from "./components/cta-sections/variants/09-faq";
import View9 from "./components/cta-sections/variants/10-split";
const views={"sunflower":View0,"floating-gallery":View1,"portrait-frame":View2,"product-window":View3,"proof-orbit":View4,"shade-panel":View5,"glow":View6,"terminal":View7,"faq":View8,"split":View9};
export interface ArtemisCtaSectionsProps{className?:string;variant?:"sunflower"|"floating-gallery"|"portrait-frame"|"product-window"|"proof-orbit"|"shade-panel"|"glow"|"terminal"|"faq"|"split";}
export function ArtemisCtaSections({className,variant="sunflower"}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}
